import{z as A,x as l,o as n,c as d,q as t,j as B,D as r,d as E,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"内部人-外部人理论","description":"","frontmatter":{"title":"内部人-外部人理论","date":"2026-09-27T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/insider-outsider-labor.md","filePath":"econ/insider-outsider-labor.md","lastUpdated":1791063341000}'),p={name:"econ/insider-outsider-labor.md"};function m(u,a,c,h,D,C){const s=l("Mermaid");return n(),d("div",null,[a[2]||(a[2]=t('<h1 id="内部人-外部人理论" tabindex="-1">内部人-外部人理论 <a class="header-anchor" href="#内部人-外部人理论" aria-label="Permalink to &quot;内部人-外部人理论&quot;">​</a></h1><div class="epigraph"><p>在职工人手握谈判筹码，失业者站在门外喊不出价：劳动市场的刚工资，一半来自门内人的市场力。</p><footer>—— 据 Lindbeck–Snower 内部人-外部人模型 (1988)；Blanchard–Summers 滞后效应 (1986)</footer></div><p><a href="/econ/household-production">家庭生产模型</a>讲时间在市场内外的套利，本课讲劳动市场内部的门槛：谁在门内（insider）、谁在门外（outsider）。缺口是解释两个刚性事实——工资为何不降出清、衰退为何留下永久疤痕。本课不做工会集体谈判的细部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>新古典劳动市场：失业压低工资，工资下降吸收失业。但欧洲 1980 年代失业率从 3% 升到 10% 后十年不回头，工资却没有明显下调。缺口：<strong>在职工人的谈判力</strong>——解雇有成本（培训、遣散、团队默契流失），使内部人能把工资抬到市场出清之上而不被门外失业者压价。</p><p><span class="marginnote">术语翻译：内部人（insider）= 在岗职工，掌握不可完全转移的专用技能与默契；外部人（outsider）= 失业者或临时工；滞后（hysteresis）= 冲击消失后失业率仍不回落——历史凝固成结构。</span></p><p><span class="marginnote">数字实例：解雇成本设为每人 2 万。企业接受「内部人工资 = 边际产出 − 2 万」仍不换人——工资被托在出清水平之上。若衰退中 10% 劳动力长期失业，技能折旧使外部人有效边际产出再降，门槛更高，失业自我固化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型骨架：企业利润 = 产出 − 工资 − 调整成本（解雇成本 + 招聘培训成本）；内部人与企业谈判工资，外部人只提供威胁点。谈判解落在「边际产出 − 解雇成本」处，高于外部人保留工资。政策含义直接：解雇成本越高，内部人租金越大，失业均衡越顽固；最小工资只是这道墙的一种砌法。</p>',9)),(n(),B(i,null,{default:r(()=>[o(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%BC%81%E4%B8%9A%3A%20%E4%BA%A7%E5%87%BA%20%E2%88%92%20%E5%B7%A5%E8%B5%84%20%E2%88%92%20%E8%B0%83%E6%95%B4%E6%88%90%E6%9C%AC%22%5D%20--%3E%20B%7B%22%E6%8D%A2%E4%B8%8D%E6%8D%A2%E4%BA%BA%3F%22%7D%0A%20%20B%20--%3E%7C%22%E8%A7%A3%E9%9B%87%2B%E6%8B%9B%E8%81%98%E6%9C%89%E6%88%90%E6%9C%AC%22%7C%20C%5B%22%E5%86%85%E9%83%A8%E4%BA%BA%E8%B0%88%E5%88%A4%E5%8A%9B%20%E2%86%91%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%B7%A5%E8%B5%84%20%3D%20%E8%BE%B9%E4%BA%A7%20%E2%88%92%20%E8%A7%A3%E9%9B%87%E6%88%90%E6%9C%AC%22%5D%0A%20%20D%20--%3E%20E%5B%22%E9%AB%98%E4%BA%8E%E5%A4%96%E9%83%A8%E4%BA%BA%E4%BF%9D%E7%95%99%E5%B7%A5%E8%B5%84%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%A4%B1%E4%B8%9A%E6%8C%81%E7%BB%AD%E4%B8%8D%E5%87%BA%E6%B8%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：门内人像持有「会员卡」的乘客——公交司机不能中途赶客（解雇成本），车满了新乘客（失业者）只能站门外；票价新旧不一，司机不降价，因为降价也换不来整车的新客。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("两个放大机制把冲击变疤痕。"),e("strong",null,"滞后机制"),E("（Blanchard–Summers）：衰退中部分内部人被永久逐出，剩下的内部人数量减少、谈判力反而增强（更少人分蛋糕），工资不降反稳——失业率的「均衡值」被冲击本身改写。"),e("strong",null,"技能折旧机制"),E("：长期失业使外部人边际产出退化，企业更不愿雇佣，形成「无工作经历 → 更难找工作」的自我实现。检验证据：西班牙 1984 年临时合同改革造出双层市场——临时工占三成但转化率低，失业对产出冲击的敏感度翻倍。")],-1)),(n(),B(i,null,{default:r(()=>[o(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%86%B2%E5%87%BB%E4%B8%BA%E4%BD%95%E7%95%99%E7%96%A4%3F%22%7D%20--%3E%7C%22%E6%BB%9E%E5%90%8E%22%7C%20R%5B%22%E5%86%85%E9%83%A8%E4%BA%BA%E5%8F%98%E5%B0%91%2C%20%E7%A7%9F%E9%87%91%E9%9B%86%E4%B8%AD%22%5D%0A%20%20R%20--%3E%20S%5B%22%E5%B7%A5%E8%B5%84%E4%B8%8D%E9%99%8D%2C%20%E5%9D%87%E8%A1%A1%E5%A4%B1%E4%B8%9A%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20Q%20--%3E%7C%22%E6%8A%80%E8%83%BD%E6%8A%98%E6%97%A7%22%7C%20T%5B%22%E5%A4%96%E9%83%A8%E4%BA%BA%E8%BE%B9%E9%99%85%E4%BA%A7%E5%87%BA%E2%86%93%22%5D%0A%20%20T%20--%3E%20U%5B%22%E9%9B%87%E4%BD%A3%E9%97%A8%E6%A7%9B%E6%9B%B4%E9%AB%98%22%5D%0A%20%20S%20--%3E%20V%5B%22%E5%A4%B1%E4%B8%9A%E8%87%AA%E6%88%91%E5%9B%BA%E5%8C%96%22%5D%0A%20%20U%20--%3E%20V%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">常见误区：把内部人-外部人工资差全归于工会——解雇成本、专用技能、招募筛选本身就是市场力来源，无工会的日本大企业内部市场同样呈现内外价差；另一误区是高解雇成本保护就业——它保护的是<strong>在岗者</strong>，代价是外部人进入更难、总体就业更弱（欧洲双层市场的教训）。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型在解雇成本高、集体谈判强的经济体解释力最强；美国式的灵活市场里，效率工资与隐性合同承担了类似角色——内部人租金小但「 segmentation 」仍在（好工作与坏工作的分界）。政策工具箱在此框架内排序：双轨合同（意大利 Jobs Act 2015 的渐进保护）、培训补贴把外部人「洗白」成内部人、失业保险与激活服务的组合。与<a href="/econ/fertility-econ">生育的经济学</a>的接口：劳动力市场双层化直接压低年轻人入职与成家决策——门外的先门都不进。</p><p><span class="marginnote">直觉类比：双层劳动市场像机场两道安检——内部人有快速通道且行李免检（解雇保护），外部人每件行李都开箱（试用、短期合同）；通道越严，愿意排队的人越少，机场（经济）整体吞吐反而下降。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>解雇与培训成本给内部人市场力，工资被托在出清水平之上。</li><li>滞后 + 技能折旧把衰退失业凝成结构失业。</li><li>政策权衡：保护在岗者 vs 降低进入门槛，双层化是常见副作用。</li><li>出处：Lindbeck–Snower「The Insider-Outsider Theory」1988；Blanchard–Summers 1986；Bentolila–Saint-Paul 西班牙双层市场研究。</li></ul>',6))])}const b=A(p,[["render",m]]);export{_ as __pageData,b as default};
